package org.emransm.moviebox.phone;
import android.content.Context;import android.graphics.*;import android.graphics.drawable.Drawable;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.Test;import org.junit.runner.RunWith;import java.io.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class LauncherIconScenarios {
 @Test public void installedApplicationIconLoadsAndRendersOnThisAndroidVersion()throws Exception{Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();Drawable icon=context.getPackageManager().getApplicationIcon(context.getPackageName());assertNotNull(icon);Bitmap bitmap=Bitmap.createBitmap(192,192,Bitmap.Config.ARGB_8888);icon.setBounds(0,0,192,192);icon.draw(new Canvas(bitmap));assertTrue("Installed icon has visible centre",Color.alpha(bitmap.getPixel(96,96))>0);try(FileOutputStream out=new FileOutputStream(new File(context.getExternalFilesDir(null),"qa-installed-launcher-icon.png"))){assertTrue(bitmap.compress(Bitmap.CompressFormat.PNG,100,out));}finally{bitmap.recycle();}}
}
